The graph shows one trigonometric function.

[tikz]
\begin{tikzpicture}
\definecolor{curveblue}{HTML}{268CFF}
\definecolor{gridgrey}{HTML}{CCCCCC}
\begin{axis}[width=10cm,height=6cm,axis lines=middle,axis line style={black},xlabel={$\theta\ (^{\circ})$},ylabel={$y$},xmin=0,xmax=385,ymin=-1.3,ymax=1.3,xtick={0,90,180,270,360},ytick={-1,-0.5,0.5,1},grid=major,grid style={gridgrey},tick label style={font=\fontsize{8.5}{10}\selectfont,text=black,fill=white},label style={font=\fontsize{10}{12}\selectfont,text=black},samples=241,clip=true]
